"""Structured preliminary technical assessment report generator."""

from __future__ import annotations

import html
from datetime import datetime, timezone
from typing import Any


DISCLAIMER_TEXT = (
    "RESEARCH PROTOTYPE ONLY — NOT A MEDICAL DEVICE. Outputs are generated by an experimental "
    "EfficientNet-B0 research classifier trained on ISIC 2019 dermoscopic images and must NOT be used "
    "for clinical diagnosis, triage, or treatment decisions without qualified clinician review and "
    "regulatory validation."
)


def build_preliminary_report(
    case_label: str,
    reviewer_notes: str,
    analysis: dict[str, Any],
) -> dict[str, str]:
    """Build sanitized HTML and Markdown preliminary technical reports from inference output."""
    timestamp = datetime.now(timezone.utc).strftime("%Y-%m-%d %H:%M UTC")
    arms = analysis.get("arms", {})
    consensus = analysis.get("consensus_diagnosis")
    max_scc = float(analysis.get("max_scc_probability", 0.0))

    arm_lines_md = []
    arm_rows_html = []
    for arm_key, arm_data in arms.items():
        label = str(arm_data.get("label", arm_key))
        pred = str(arm_data.get("predicted_diagnosis", "N/A"))
        full_name = str(arm_data.get("predicted_full_name", ""))
        conf = float(arm_data.get("predicted_confidence", 0.0))
        scc_p = float(arm_data.get("scc_probability", 0.0))
        cam_target = str(arm_data.get("gradcam_target", pred))

        arm_lines_md.append(
            f"| {label} | {pred} ({full_name}) | {conf * 100:.1f}% | {scc_p * 100:.1f}% | {cam_target} |"
        )
        arm_rows_html.append(
            "<tr>"
            f"<td>{html.escape(label)}</td>"
            f"<td><strong>{html.escape(pred)}</strong> ({html.escape(full_name)})</td>"
            f"<td>{conf * 100:.1f}%</td>"
            f"<td>{scc_p * 100:.1f}%</td>"
            f"<td>{html.escape(cam_target)}</td>"
            "</tr>"
        )

    consensus_str = (
        f"All arms agree on {consensus}" if consensus else "Cross-arm disagreement detected (manual inspection advised)"
    )
    notes_clean = reviewer_notes.strip() or "No additional reviewer notes recorded."

    markdown = "\n".join([
        "# GenAI Jury — Preliminary Technical Assessment Report",
        "",
        f"**Generated:** {timestamp}  ",
        f"**Case Reference:** {case_label}  ",
        f"**Cross-Arm Status:** {consensus_str}  ",
        f"**Peak SCC Probability Across Arms:** {max_scc * 100:.1f}%",
        "",
        f"> **SAFETY NOTICE:** {DISCLAIMER_TEXT}",
        "",
        "## Model Comparison Summary",
        "",
        "| Training Arm | Top Prediction | Confidence | SCC Probability | Grad-CAM Target |",
        "|---|---|---:|---:|---|",
        *arm_lines_md,
        "",
        "## Reviewer Notes",
        "",
        notes_clean,
        "",
        "## Methodological Context",
        "",
        "- Baseline (`real_only`) achieved the highest held-out SCC F1 (`0.354`) and PR-AUC (`0.340`) across 3,664 real test lesions.",
        "- Spatial Grad-CAM overlays inspect `EfficientNet-B0` final convolutional activations (`7x7` feature grid upsampled to `224x224`) to flag whether attention focuses on lesion morphology or borders/artifacts.",
    ])

    safe_case = html.escape(case_label)
    safe_notes = html.escape(notes_clean)
    safe_consensus = html.escape(consensus_str)
    safe_disclaimer = html.escape(DISCLAIMER_TEXT)
    html_doc = f"""<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <title>GenAI Jury Preliminary Technical Report — {safe_case}</title>
  <style>
    body {{ font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif; color: #172b4d; max-width: 820px; margin: 2rem auto; padding: 0 1.5rem; line-height: 1.5; }}
    .banner {{ border: 2px solid #9b1c1c; background: #fdecec; color: #7f1d1d; padding: 0.9rem 1rem; border-radius: 8px; font-size: 0.92rem; margin: 1rem 0 1.5rem; }}
    h1 {{ color: #0b2545; border-bottom: 2px solid #0f766e; padding-bottom: 0.4rem; }}
    table {{ width: 100%; border-collapse: collapse; margin: 1rem 0; }}
    th, td {{ border: 1px solid #cbd5e1; padding: 0.55rem 0.7rem; text-align: left; font-size: 0.92rem; }}
    th {{ background: #eaf2f8; color: #0b2545; }}
    .meta {{ display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 0.5rem 1.5rem; background: #f8fafc; padding: 0.85rem 1rem; border-radius: 8px; border: 1px solid #e2e8f0; }}
  </style>
</head>
<body>
  <h1>GenAI Jury — Preliminary Technical Assessment</h1>
  <div class="banner"><strong>IMPORTANT LIMITATION:</strong> {safe_disclaimer}</div>
  <div class="meta">
    <div><strong>Case Reference:</strong> {safe_case}</div>
    <div><strong>Timestamp:</strong> {html.escape(timestamp)}</div>
    <div><strong>Cross-Arm Agreement:</strong> {safe_consensus}</div>
    <div><strong>Peak SCC Probability:</strong> {max_scc * 100:.1f}%</div>
  </div>
  <h2>3-Arm Classifier Comparison</h2>
  <table>
    <thead>
      <tr><th>Training Arm</th><th>Top Prediction</th><th>Confidence</th><th>SCC Probability</th><th>Grad-CAM Target</th></tr>
    </thead>
    <tbody>
      {"".join(arm_rows_html)}
    </tbody>
  </table>
  <h2>Reviewer Notes</h2>
  <p>{safe_notes}</p>
</body>
</html>"""

    return {
        "generated_at": timestamp,
        "markdown": markdown,
        "html": html_doc,
    }
